89	     * Remembers, per seen idempotency key, the id of the owner that create originally produced, so a
90	     * repeat of the same request returns that owner rather than creating a duplicate.
91	     */
92	    private final Map<String, Integer> idempotentCreates = new java.util.concurrent.ConcurrentHashMap<>();
