148	    @Override
149	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
150	        HttpHeaders headers = new HttpHeaders();
151	        String idempotencyKey = currentIdempotencyKey();
152	        if (idempotencyKey != null) {
153	            Integer existingId = idempotentCreates.get(idempotencyKey);
154	            if (existingId != null) {
155	                Owner existing = this.clinicService.findOwnerById(existingId);
156	                if (existing != null) {
157	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
158	                    applyMembership(existingDto, existing);
159	                    existingDto.setBulkSignupWarning(isBulkSignupDay());
160	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
161	                }
162	            }
163	        }
164	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
165	        String address = applyAddress(owner, ownerFieldsDto);
166	        if (address.isEmpty()) {
167	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
168	        }
169	        owner.setAddress(address);
170	        String telephone = toE164(owner.getTelephone());
171	        if (telephone == null) {
172	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
173	        }
174	        owner.setTelephone(telephone);
175	        if (owner.getEmail() != null) {
176	            String email = normalizeEmail(owner.getEmail());
177	            if (email == null) {
178	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
179	            }
180	            owner.setEmail(email);
181	        }
182	        if (owner.getPostcode() != null && !isValidPostcode(owner.getPostcode(), owner.getCity())) {
183	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	        }
185	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
186	        if (effectiveRegistrationDate == null) {
187	            effectiveRegistrationDate = LocalDate.now();
188	        }
189	        else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
190	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
191	        }
192	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
193	        owner.setRegistrationDate(registrationDate);
194	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
195	            return new ResponseEntity<>(HttpStatus.CONFLICT);
196	        }
197	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
198	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
199	        }
200	        // The householdId is deterministic: the first twelve hex characters of SHA-256 over
201	        // '<normalizedLastName>|<postcode>'. Owners sharing a last name and postcode therefore
202	        // share the household automatically. An owner without a postcode has no household.
203	        boolean declaredHouseholdMember = false;
204	        if (owner.getPostcode() != null) {
205	            String householdId = householdId(householdKey(owner.getLastName()), owner.getPostcode());
206	            owner.setHouseholdId(householdId);
207	            // A second owner sharing a household (same lastName + postcode) but with a distinct
208	            // identity is a legitimate additional household member — true duplicates are still
209	            // caught by the identityKey check below. 'sharesHousehold' opts such an owner in as a
210	            // declared member so it is not additionally flagged as a possible duplicate.
211	            boolean householdOccupied = false;
212	            for (Owner existing : this.clinicService.findAllOwners()) {
213	                if (existing.isDeleted()) {
214	                    continue;
215	                }
216	                if (householdId.equals(computeHouseholdId(existing))) {
217	                    householdOccupied = true;
218	                    break;
219	                }
220	            }
221	            if (householdOccupied && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
222	                declaredHouseholdMember = true;
223	            }
224	        }
225	        // Consolidated duplicate detection: reject only when the whole identityKey
226	        // (SHA-256 over normalizedTelephone | lowerEmail | soundex(lastName)) matches an
227	        // existing owner's. This is the single duplicate check; owners sharing a household
228	        // (same last name and postcode) but with different telephones produce different keys
229	        // and are no longer rejected here — they surface as soft matches below.
230	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
231	        for (Owner existing : this.clinicService.findAllOwners()) {
232	            if (existing.isDeleted()) {
233	                continue;
234	            }
235	            if (identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
236	                existing.getEmail(), existing.getLastName()))) {
237	                return new ResponseEntity<>(HttpStatus.CONFLICT);
238	            }
239	        }
240	        // Soft-match: the owner is not a hard (identityKey) duplicate, but if it shares an
241	        // existing owner's last name and postcode while having a different normalized
242	        // telephone it is still created and flagged as a possible duplicate of that owner. A
243	        // declared household member, however, is not a suspected duplicate, so it is never flagged.
244	        if (declaredHouseholdMember) {
245	            owner.setPossibleDuplicate(false);
246	        }
247	        else {
248	            applyPossibleDuplicate(owner);
249	        }
250	        owner.setCustomerCode(deduplicatedCustomerCode(
251	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName())));
252	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
253	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
254	        this.clinicService.saveOwner(owner);
255	        if (idempotencyKey != null) {
256	            idempotentCreates.put(idempotencyKey, owner.getId());
257	        }
258	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
259	        Map<String, Integer> householdSizes = householdSizes();
260	        applyMembership(ownerDto, owner, householdSizes);
261	        capMembershipLevelToHousehold(ownerDto, owner, householdSizes);
262	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
263	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
264	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
265	        emitOwnerCreatedEvent(owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
266	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
267	        headers.setLocation(UriComponentsBuilder.newInstance()
268	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
269	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
270	    }
