303	     * Reads the {@code Idempotency-Key} header of the request currently being handled, used to make
304	     * owner creation idempotent. Returns the trimmed key when present and non-blank, otherwise
305	     * {@code null} (including when there is no active servlet request), so a missing or blank key
306	     * simply means "no idempotency" and the create proceeds normally.
307	     *
308	     * @return the current request's idempotency key, or {@code null} when none is supplied
309	     */
310	    private static String currentIdempotencyKey() {
311	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
