442	    /**
443	     * The maximum number of owners that may be created in a single business day. Owner
444	     * creation is rejected once this many owners already fall on the new owner's adjusted
445	     * business day {@code registrationDate}.
446	     */
447	    private static final int MAX_OWNERS_PER_DAY = 100;
448	
449	    /**
450	     * The fixed list of public holidays that the business-day roll skips over. A date that
451	     * lands on one of these is rolled forward to the next non-holiday business day.
452	     */
453	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
454	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
455	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
456	        LocalDate.parse("2026-12-28"));
457	
458	    /**
459	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public
460	     * holiday is moved forward one day at a time until a non-holiday weekday is reached,
461	     * while a date that is already a non-holiday weekday is returned unchanged.
462	     *
463	     * @param date the date to adjust
464	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
465	     */
466	    private LocalDate toBusinessDay(LocalDate date) {
467	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
468	                || PUBLIC_HOLIDAYS.contains(date)) {
469	            date = date.plusDays(1);
470	        }
471	        return date;
472	    }
