474	    /**
475	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
476	     * registrationDate} rolls forward to the same business day. This is evaluated before the
477	     * new owner is persisted, so the owner being created is not included in the count.
478	     *
479	     * @param businessDay the adjusted business day to count against
480	     * @return the number of existing owners registered on that business day
481	     */
482	    private int countOwnersRegisteredOn(LocalDate businessDay) {
483	        int count = 0;
484	        for (Owner existing : this.clinicService.findAllOwners()) {
485	            LocalDate existingDate = existing.getRegistrationDate();
486	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
487	                count++;
488	            }
489	        }
490	        return count;
491	    }
