511	    /**
512	     * Builds the customer code for a newly created owner, formatted
513	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the canonical region
514	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
515	     * {@code "UNKNOWN"} when the postcode resolves no region) and {@code HASH8} is the
516	     * first eight upper-case hex characters of the SHA-256 digest of
517	     * {@code normalizedTelephone + lastName}. The code carries no sequence number, so it is
518	     * stable for a given telephone and last name rather than dependent on creation order.
519	     *
520	     * @param postcode            the owner's postcode (may be {@code null})
521	     * @param normalizedTelephone the owner's normalized E.164 telephone
522	     * @param lastName            the owner's last name
523	     * @return the assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
524	     */
525	    private static String customerCode(String postcode, String normalizedTelephone, String lastName) {
526	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
527	        return region + "-" + sha256Hex8(normalizedTelephone + lastName);
528	    }
529	
530	    /**
531	     * De-duplicates a freshly computed {@code base} customer code against the codes already
532	     * assigned to existing owners. When {@code base} is free it is returned unchanged;
533	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of two or more that
534	     * yields a code no existing owner holds.
535	     *
536	     * @param base the computed {@code '<REGION>-<HASH8>'} customer code
537	     * @return {@code base}, or {@code base + "-<n>"} de-duplicated to be unique
538	     */
539	    private String deduplicatedCustomerCode(String base) {
540	        Set<String> existing = new HashSet<>();
541	        for (Owner owner : this.clinicService.findAllOwners()) {
542	            if (owner.getCustomerCode() != null) {
543	                existing.add(owner.getCustomerCode());
544	            }
545	        }
546	        if (!existing.contains(base)) {
547	            return base;
548	        }
549	        int n = 2;
550	        while (existing.contains(base + "-" + n)) {
551	            n++;
552	        }
553	        return base + "-" + n;
554	    }
555	
556	    /**
557	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
558	     * bytes of {@code source} — the {@code HASH8} component of an owner's customer code.
559	     *
560	     * @param source the string to hash
561	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
562	     */
563	    private static String sha256Hex8(String source) {
564	        try {
565	            byte[] digest = MessageDigest.getInstance("SHA-256")
566	                .digest(source.getBytes(StandardCharsets.UTF_8));
567	            StringBuilder hex = new StringBuilder(digest.length * 2);
568	            for (byte b : digest) {
569	                hex.append(String.format("%02x", b));
570	            }
571	            return hex.substring(0, 8).toUpperCase();
572	        } catch (NoSuchAlgorithmException e) {
573	            throw new IllegalStateException("SHA-256 not available", e);
574	        }
575	    }
