577	    /**
578	     * Builds the membership number for a newly created owner, formatted
579	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
580	     * customer code and {@code YY} is the last two digits of the fiscal year of the owner's
581	     * business-day-adjusted registration date, zero-padded to two digits. The fiscal year
582	     * starts on 1 July and is named by the calendar year it ends in.
583	     *
584	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
585	     * @param registrationDate the owner's business-day-adjusted registration date
586	     * @return the assigned membership number (e.g. {@code 'NSW-1A2B3C4D-M27'})
587	     */
588	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
589	        int fiscalYear = org.springframework.samples.petclinic.mapper.FiscalYear.yearValue(registrationDate);
590	        return String.format("%s-M%02d", customerCode, Math.floorMod(fiscalYear, 100));
591	    }
