613	    /**
614	     * Canonical expansions applied to common street-type abbreviations during address
615	     * normalization. Keys and values are upper-cased so the lookup runs after the address
616	     * has itself been upper-cased.
617	     */
618	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
619	        "ST", "STREET",
620	        "RD", "ROAD",
621	        "AVE", "AVENUE");
622	
623	    /**
624	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
625	     * every run of internal whitespace is collapsed to a single space, the result is
626	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
627	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
628	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
629	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
630	     * returned and compared for household duplicates; an address that is blank once
631	     * normalized fails the required-field check.
632	     *
633	     * @param address the raw address value supplied by the client
634	     * @return the normalized address (empty string when {@code address} is null or blank)
635	     */
636	    /**
637	     * Normalizes the address an owner supplies, preferring the structured form, and stores the
638	     * normalized structured lines on the owner. When a non-blank {@code addressLine1} is present
639	     * the structured fields are used: {@code addressLine1} (and {@code addressLine2}, when
640	     * present) are {@link #normalizeAddress normalized} and set on the owner, and the composed
641	     * address returned is the normalized {@code addressLine1} with a single space and the
642	     * normalized {@code addressLine2} appended when {@code addressLine2} is present. Otherwise
643	     * the flat {@code address} is normalized and returned, and the structured lines are left
644	     * unset. The returned value becomes the owner's stored {@code address}, read by everything
645	     * downstream (household hash, postcode validation and locality); an owner that supplies
646	     * neither form yields an empty string, failing the required-address check.
647	     *
648	     * @param owner          the owner being created, whose structured address lines are set here
649	     * @param ownerFieldsDto the submitted owner fields
650	     * @return the composed, normalized address (empty string when no address form is supplied)
651	     */
652	    private static String applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
653	        String addressLine1 = ownerFieldsDto.getAddressLine1();
654	        if (addressLine1 != null && !addressLine1.isBlank()) {
655	            String normalizedLine1 = normalizeAddress(addressLine1);
656	            owner.setAddressLine1(normalizedLine1);
657	            String addressLine2 = ownerFieldsDto.getAddressLine2();
658	            if (addressLine2 != null && !addressLine2.isBlank()) {
659	                String normalizedLine2 = normalizeAddress(addressLine2);
660	                owner.setAddressLine2(normalizedLine2);
661	                return normalizedLine1 + " " + normalizedLine2;
662	            }
663	            owner.setAddressLine2(null);
664	            return normalizedLine1;
665	        }
666	        owner.setAddressLine1(null);
667	        owner.setAddressLine2(null);
668	        return normalizeAddress(ownerFieldsDto.getAddress());
669	    }
670	
671	    private static String normalizeAddress(String address) {
672	        if (address == null) {
673	            return "";
674	        }
675	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
676	        if (collapsed.isEmpty()) {
677	            return "";
678	        }
679	        StringBuilder normalized = new StringBuilder(collapsed.length());
680	        for (String token : collapsed.split(" ")) {
681	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
682	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
683	            if (normalized.length() > 0) {
684	                normalized.append(' ');
685	            }
686	            normalized.append(expanded != null ? expanded : token);
687	        }
688	        return normalized.toString();
689	    }
690	
691	    /**
692	     * Normalizes a last name or address for household-duplicate comparison: leading and
693	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
694	     * single space and the result is lower-cased. Two owners are considered to share a
695	     * household when both their last names and addresses produce the same key.
696	     *
697	     * @param value the raw last name or address value
698	     * @return the normalized comparison key (empty string when {@code value} is null)
699	     */
700	    private static String householdKey(String value) {
701	        if (value == null) {
702	            return "";
703	        }
704	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
705	    }
706	
707	    /**
708	     * Derives the stable shared household identifier for the given normalized last name key
709	     * and postcode. The identifier is deterministic — the same household (same
710	     * {@link #householdKey normalized} last name and postcode) always maps to the same
711	     * value — so every owner in a household is assigned an identical id. It is the
712	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
713	     * '<lastNameKey>|<postcode>'}.
714	     *
715	     * @param lastNameKey the normalized last name key
716	     * @param postcode    the owner's postcode
717	     * @return the shared household identifier
718	     */
719	    private static String householdId(String lastNameKey, String postcode) {
720	        String source = lastNameKey + "|" + postcode;
721	        try {
722	            byte[] digest = MessageDigest.getInstance("SHA-256")
723	                .digest(source.getBytes(StandardCharsets.UTF_8));
724	            StringBuilder hex = new StringBuilder(digest.length * 2);
725	            for (byte b : digest) {
726	                hex.append(String.format("%02x", b));
727	            }
728	            return hex.substring(0, 12).toUpperCase();
729	        } catch (NoSuchAlgorithmException e) {
730	            throw new IllegalStateException("SHA-256 not available", e);
731	        }
732	    }
733	
734	    /**
735	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
736	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
737	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
738	     * collides with a computed household id.
739	     *
740	     * @param owner the existing owner
741	     * @return the owner's household id, or {@code null} when it has no postcode
742	     */
743	    private static String computeHouseholdId(Owner owner) {
744	        if (owner.getPostcode() == null) {
745	            return null;
746	        }
747	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
748	    }
