750	    /**
751	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
752	     * dto, sizing the owner's household from all owners so the household-of-three-or-more
753	     * factor is scored correctly. Use {@link #applyMembership(OwnerDto, Owner, Map)} instead
754	     * when mapping a collection to size every household from a single scan.
755	     *
756	     * @param ownerDto the dto to populate
757	     * @param owner    the owner being mapped
758	     */
759	    private void applyMembership(OwnerDto ownerDto, Owner owner) {
760	        applyMembership(ownerDto, owner, householdSizes());
761	    }
762	
763	    /**
764	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
765	     * dto using a pre-computed map of household id to member count.
766	     *
767	     * @param ownerDto       the dto to populate
768	     * @param owner          the owner being mapped
769	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
770	     */
771	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
772	        int householdSize = owner.getHouseholdId() == null ? 1
773	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
774	        int points = MembershipPoints.points(owner, householdSize);
775	        ownerDto.setMembershipPoints(points);
776	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
777	    }
778	
779	    /**
780	     * Caps a newly created owner's {@code membershipLevel} at one above the highest
781	     * {@code membershipLevel} among the other current members of its household, writing the
782	     * capped value back onto the dto and returning it. A member's current level is scored the
783	     * same way as {@link #applyMembership}, using {@code householdSizes} so the
784	     * household-of-three-or-more factor reflects the household as it now stands. When the owner
785	     * has no household, or is the only member of its household, no cap applies and the level is
786	     * returned unchanged.
787	     *
788	     * @param ownerDto       the newly created owner's dto, with its uncapped membership already applied
789	     * @param owner          the newly created owner (already saved, so it has an id)
790	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
791	     * @return the resulting (possibly capped) membership level
792	     */
793	    private int capMembershipLevelToHousehold(OwnerDto ownerDto, Owner owner,
794	        Map<String, Integer> householdSizes) {
795	        int level = ownerDto.getMembershipLevel();
796	        String householdId = owner.getHouseholdId();
797	        if (householdId == null) {
798	            return level;
799	        }
800	        Integer maxMemberLevel = null;
801	        for (Owner existing : this.clinicService.findAllOwners()) {
802	            if (existing.isDeleted() || existing.getId().equals(owner.getId())) {
803	                continue;
804	            }
805	            if (householdId.equals(existing.getHouseholdId())) {
806	                int size = householdSizes.getOrDefault(householdId, 1);
807	                int memberLevel = MembershipPoints.level(MembershipPoints.points(existing, size));
808	                maxMemberLevel = maxMemberLevel == null ? memberLevel
809	                    : Math.max(maxMemberLevel, memberLevel);
810	            }
811	        }
812	        if (maxMemberLevel != null && level > maxMemberLevel + 1) {
813	            level = maxMemberLevel + 1;
814	            ownerDto.setMembershipLevel(level);
815	        }
816	        return level;
817	    }
818	
819	    /**
820	     * Counts how many owners belong to each household, keyed by household id. Owners without a
821	     * household id (no postcode) are excluded — such an owner is its own single-member household.
822	     *
823	     * @return a map from household id to the number of owners sharing it
824	     */
825	    private Map<String, Integer> householdSizes() {
826	        Map<String, Integer> sizes = new java.util.HashMap<>();
827	        for (Owner existing : this.clinicService.findAllOwners()) {
828	            String householdId = existing.getHouseholdId();
829	            if (householdId != null) {
830	                sizes.merge(householdId, 1, Integer::sum);
831	            }
832	        }
833	        return sizes;
834	    }
835	
836	    /**
837	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
838	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
839	     * possible duplicate when a non-deleted existing owner shares its {@link
840	     * OwnerIdentity#soundex soundex(lastName)} and its postcode while producing a different
841	     * {@code identityKey}; {@code possibleDuplicateOf} is then set to that existing owner's id.
842	     * Because the telephone is part of the identity key, two owners with the same last name and
843	     * postcode but different telephones differ in their keys and so surface here as a soft match
844	     * rather than a hard duplicate. When several existing owners match, the one with the lowest
845	     * id is chosen so the result is deterministic. When no such owner exists — or the new owner
846	     * has no postcode to compare — {@code possibleDuplicate} is set to {@code false} and no
847	     * matching id is recorded.
848	     *
849	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
850	     */
851	    private void applyPossibleDuplicate(Owner owner) {
852	        owner.setPossibleDuplicate(false);
853	        if (owner.getPostcode() == null) {
854	            return;
855	        }
856	        String soundex = OwnerIdentity.soundex(owner.getLastName());
857	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
858	        Owner match = null;
859	        for (Owner existing : this.clinicService.findAllOwners()) {
860	            if (existing.isDeleted()) {
861	                continue;
862	            }
863	            if (soundex.equals(OwnerIdentity.soundex(existing.getLastName()))
864	                && owner.getPostcode().equals(existing.getPostcode())
865	                && !identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
866	                    existing.getEmail(), existing.getLastName()))) {
867	                if (match == null || (existing.getId() != null
868	                    && existing.getId() < match.getId())) {
869	                    match = existing;
870	                }
871	            }
872	        }
873	        if (match != null) {
874	            owner.setPossibleDuplicate(true);
875	            owner.setPossibleDuplicateOf(match.getId());
876	        }
877	    }
878	
879	    /**
880	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
881	     * and brackets are stripped. When the number already carries a leading {@code '+'}
882	     * and country code these are kept; a number written in national trunk form (a leading
883	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
884	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
885	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
886	     * after the {@code '+'}, and its national-number length must be valid for the detected
887	     * country code (see {@link #hasValidNationalLength}).
888	     *
889	     * @param telephone the raw telephone value supplied by the client
890	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
891	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
892	     */
893	    private static String toE164(String telephone) {
894	        if (telephone == null) {
895	            return null;
896	        }
897	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
898	        String digits;
899	        if (cleaned.startsWith("+")) {
900	            digits = cleaned.substring(1);
901	        } else if (cleaned.startsWith("0")) {
902	            digits = "61" + cleaned.substring(1);
903	        } else {
904	            digits = "1" + cleaned;
905	        }
906	        if (!digits.matches("[0-9]{8,15}")) {
907	            return null;
908	        }
909	        if (!hasValidNationalLength(digits)) {
910	            return null;
911	        }
912	        return "+" + digits;
913	    }
914	
915	    /**
916	     * Validates the national-number length of an E.164 digit string against its country
917	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
918	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
919	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
920	     *
921	     * @param digits the E.164 digits (without the leading {@code '+'})
922	     * @return {@code true} when the national-number length is valid for the country code
923	     */
924	    private static boolean hasValidNationalLength(String digits) {
925	        if (digits.startsWith("61")) {
926	            return digits.length() - 2 == 9;
927	        }
928	        if (digits.startsWith("1")) {
929	            return digits.length() - 1 == 10;
930	        }
931	        return true;
932	    }
933	
934	    /**
935	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
936	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
937	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
938	     */
939	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
940	        "NSW", new int[] {2000, 2099},
941	        "VIC", new int[] {3000, 3099},
942	        "QLD", new int[] {4000, 4099});
943	
944	    /**
945	     * Validates an owner's postcode for creation. A postcode is only ever validated when
946	     * present (an absent postcode is optional and accepted). When present it must be exactly
947	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
948	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
949	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
950	     *
951	     * @param postcode the supplied postcode (never {@code null} here)
952	     * @param city     the owner's city, used to derive the region
953	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
954	     *         (signalling a 400 Bad Request)
955	     */
956	    private static boolean isValidPostcode(String postcode, String city) {
957	        if (!postcode.matches("[0-9]{4}")) {
958	            return false;
959	        }
960	        int[] range = REGION_POSTCODES.get(
961	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
962	        if (range == null) {
963	            return true;
964	        }
965	        int value = Integer.parseInt(postcode);
966	        return value >= range[0] && value <= range[1];
967	    }
968	
969	    /**
970	     * Disposable email domains that are not accepted for owner creation. An owner whose
971	     * email domain (compared case-insensitively) is in this set is rejected with a 400
972	     * Bad Request.
973	     */
974	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
975	        "mailinator.com", "tempmail.com", "guerrillamail.com");
976	
977	    /**
978	     * Normalizes an owner email for creation. A present email must be a syntactically
979	     * valid address whose domain is not on the disposable-domain blocklist ({@link
980	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
981	     *
982	     * @param email the raw email value supplied by the client (never {@code null} here)
983	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
984	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
985	     */
986	    private static String normalizeEmail(String email) {
987	        String trimmed = email.trim();
988	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
989	            return null;
990	        }
991	        String normalized = trimmed.toLowerCase();
992	        String domain = normalized.substring(normalized.indexOf('@') + 1);
993	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
994	            return null;
995	        }
996	        return normalized;
997	    }
998	}
